const newId=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'local-'+Date.now()+'-'+Math.random().toString(36).slice(2);
function validData(x){return x&&typeof x==='object'&&!Array.isArray(x)&&x.profile&&typeof x.profile==='object'&&/^\d{4}-\d{2}-\d{2}$/.test(x.profile.startDate||'')&&Array.isArray(x.profile.equipment)&&Array.isArray(x.measurements)&&x.sessions&&typeof x.sessions==='object'&&!Array.isArray(x.sessions)}
function loadProfiles(){
 try{
   const raw=localStorage.getItem(MULTI_STORAGE);
   if(raw){const o=JSON.parse(raw);if(o&&o.version===2&&Array.isArray(o.profiles)){
     o.profiles=o.profiles.filter(x=>x&&typeof x.id==='string'&&validData(x.data)).slice(0,30);
     if(!o.profiles.some(x=>x.id===o.activeId))o.activeId=o.profiles[0]?.id||null;
     return {version:2,profiles:o.profiles,activeId:o.activeId};
   }}
 }catch(e){}
 try{
   const legacy=JSON.parse(localStorage.getItem(STORAGE)||'null');
   if(validData(legacy)){
     const id=newId();return {version:2,profiles:[{id,createdAt:new Date().toISOString(),data:{...defaultStore(),...legacy}}],activeId:id};
   }
 }catch(e){}
 return {version:2,profiles:[],activeId:null};
}
