function planLength(){return db.profile?.weeks==='47d'?47:Math.max(28,Math.min(84,7*Number(db.profile?.weeks||8)))}
function safeIndex(s){return db.profile?Math.max(0,Math.min(planLength()-1,dateDiff(s,db.profile.startDate))):0}
function selectDate(s){if(!db.profile)return;selected=datePlus(db.profile.startDate,safeIndex(s));page='plan';render()}
function planIndex(){return safeIndex(selected)}
function dayPlan(s=selected){const off=safeIndex(s),wk=Math.floor(off/7),day=off%7;const t=planTemplates[day];let items=[...t.items];if(db.profile.equipment.includes('Kettlebell') && day===2)items=items.map(id=>id==='rdl'?'kettlerdl':id);
 if(db.profile.equipment.includes('Barbell') && day===4)items=items.map(id=>id==='row'?'barrow':id);
 if(!db.profile.equipment.includes('Dumbbell')){
 const fallback={floor:'pushup',row:'bird',press:'incline',goblet:'bodySquat',rdl:db.profile.equipment.includes('Kettlebell')?'kettlerdl':'bridge',carry:'plank'};
 items=items.map(i=>fallback[i]||i);
}
 const weekday=dateObj(s).getDay();
 const routine=(db.routines||[]).filter(r=>r.active!==false && Array.isArray(r.days) && r.days.includes(weekday) && (!r.startDate || r.startDate<=s)).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')))[0];
 if(routine){items=(routine.exercises||[]).filter(e=>exercises[e.id]).map(e=>e.id);}
 const replacementForDate=db.daySwaps?.[s]||{};
 items=items.map(id=>replacementForDate[id]&&exercises[replacementForDate[id].id]?replacementForDate[id].id:id);
 const strength=routine?routine.kind!=='Recovery'&&routine.kind!=='Cardio':t.tone==='Strength';
 const sets=routine?Number(routine.sets||2):(strength?(wk<2?2:3):2);
 return {...t,...(routine?{title:routine.title,label:'CUSTOM',tone:routine.kind||'Strength',desc:'Your recurring weekly routine · '+routine.exercises.length+' selected exercises',warm:'Gentle movement and one easy practice set before lifting.'}:{}),routineId:routine?.id||null,items,sets,week:wk+1,index:off+1,date:s,phase:wk<2?'Foundation':wk<5?'Build consistency':'Progress gradually',sessionMinutes:Number(db.profile.duration)||35};
}
function hasProfile(){return Boolean(db.profile&&db.profile.startDate)}
