function nutritionPage(){const diet=db.profile.diet||'all';const filtered=foods.filter(x=>diet==='all'||x.diet.includes(diet));const searched=shopMode==='all'?filtered:filtered.filter(x=>x.c===shopMode);return `<div class="page"><div class="page-head"><div><span class="eyebrow">PRACTICAL EATING · COSTCO-FRIENDLY IDEAS</span><h1>Fuel your life, not a crash diet.</h1><p>Choose meals you enjoy and can repeat. A daily salad is a great habit when it includes protein, fiber and a sensible dressing portion; salad alone is not a complete weight-management strategy.</p></div><span class="chip">Preference: ${escapeHTML(diet==='all'?'Flexible':diet==='dairyfree'?'Dairy-free':diet)}</span></div>
 <div class="nutrition-hero"><span class="eyebrow">THE SIMPLE PLATE METHOD</span><h2>Build your own plate.</h2><div class="columns-3"><div><b>½ plate</b><p class="muted">Vegetables and fruit. Think greens, cucumber, tomato, berries and cooked vegetables.</p></div><div><b>¼ plate</b><p class="muted">A protein-rich food such as fish, chicken, tofu, beans, lentils or yogurt.</p></div><div><b>¼ plate</b><p class="muted">Whole grains or starchy vegetables. Add healthy fats in moderate portions.</p></div></div><p class="footnote">Choose portions consistent with your hunger, training, and nutritional needs. People requiring medical nutrition therapy should use individualized clinical advice.</p></div>
 <div class="section-top"><div><h2>Flexible seven-day meal chart</h2><p>Swap days, recipes, proteins and side dishes freely; these are examples, not compulsory meal prescriptions.</p></div></div><div class="card" style="overflow:auto"><table class="meal-table"><thead><tr><th>Day</th><th>Breakfast</th><th>Lunch / big salad</th><th>Dinner</th><th>Snack</th></tr></thead><tbody>${mealPlans.map(r=>`<tr>${r.map(v=>`<td>${escapeHTML(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>
 <div class="section-top"><div><h2>Your Costco grocery checklist</h2><p>Category-based ideas, not a verified live inventory or current pricing. Select items you need.</p></div>${button('Clear checks','data-action="clear-shopping"','btn btn-outline btn-sm')}</div><div class="pills mb8">${['all','Protein','Produce','Grains','Fats','Staples'].map(c=>`<button data-shop="${c}" class="${shopMode===c?'active':''}">${c==='all'?'All groups':c}</button>`).join('')}</div><div class="food-list">${searched.map(f=>`<label class="food-item"><input type="checkbox" data-food="${escapeHTML(f.n)}" ${db.shopping.includes(f.n)?'checked':''}><span><b>${escapeHTML(f.n)}</b><small class="muted" style="display:block">${escapeHTML(f.c)}</small></span></label>`).join('')}</div>
 <div class="columns-2 mt24"><div class="card"><h3>Daily salad formula</h3><ol class="nextsteps"><li>Base: spinach, kale or mixed greens.</li><li>Add colorful vegetables and beans.</li><li>Add a protein source (e.g., chicken, salmon, tofu).</li><li>Add a portion of grains if desired.</li><li>Finish with olive oil + lemon or a measured dressing.</li></ol></div><div class="card"><h3>Nutrition habits that matter</h3><ol class="nextsteps"><li>Plan a protein source at each main meal.</li><li>Eat fiber-rich fruit, vegetables and legumes.</li><li>Stay hydrated; choose unsweetened drinks often.</li><li>Shop and prepare foods you'll actually eat.</li><li>Maintain a manageable energy deficit if weight loss is appropriate; avoid extreme diets.</li></ol></div></div>
 <p class="footnote mt16">References: <a class="link" href="https://food-guide.canada.ca/en/healthy-eating-recommendations/" target="_blank" rel="noopener noreferrer">Canada's Food Guide</a>. This food guide does not recommend supplements or individualized calorie targets. Food availability differs by store, date and region.</p></div>`}
function settingsPage(){const p=db.profile;return `<div class="page"><div class="page-head"><div><span class="eyebrow">PERSONALIZATION & DATA CONTROL</span><h1>Make it work for you.</h1><p>The current profile’s settings influence its own calendar, exercise selections and weight display. ${cloudReady?'Your data is stored in your private Supabase account.':'Your measurements stay in this browser.'} Personal records are never committed to the public GitHub repository.</p></div></div>
 <div class="columns-2"><div class="card"><div class="flex spread" style="gap:10px;flex-wrap:wrap"><h2>Profile & training settings</h2>${button("Switch profile",'data-page="profiles"',"btn btn-outline btn-sm")}</div><form id="preferencesForm"><div class="form-grid"><label class="field"><span>Display name</span><input name="name" value="${escapeHTML(p.name)}" maxlength="35" required></label><label class="field"><span>Profile icon</span><select name="avatar">${AVATARS.map(x=>`<option value="${x}" ${p.avatar===x?'selected':''}>${x} Profile icon</option>`).join('')}</select></label><label class="field"><span>Age</span><input name="age" type="number" min="18" max="100" value="${p.age}" required></label><label class="field"><span>Height (cm)</span><input name="height" type="number" min="100" max="240" value="${p.height}" required></label><label class="field"><span>Optional goal (${unitText()})</span><input name="goal" type="number" min="20" max="1000" step="0.1" value="${p.goalWeightKg?formatNumber(displayWeight(p.goalWeightKg),1):''}"></label><label class="field"><span>Training background</span><select name="experience">${[['beginner','New to training'],['returning','Returning / rebuilding'],['regular','Training consistently']].map(([v,t])=>`<option value="${v}" ${p.experience===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>Dumbbell maximum (kg EACH)</span><input type="number" name="maxDB" min="0" max="150" step="0.5" value="${p.maxDB}"></label><label class="field"><span>Program length</span><select name="weeks">${[6,8,12,'47d'].map(w=>`<option ${p.weeks==w?'selected':''} value="${w}">${w==='47d'?'47-day comeback':w+' weeks'}</option>`).join('')}</select></label><label class="field"><span>Start date</span><input type="date" name="start" required value="${p.startDate}"></label><label class="field"><span>Session duration</span><select name="duration">${[25,35,45].map(n=>`<option value="${n}" ${p.duration==n?'selected':''}>${n} minutes</option>`).join('')}</select></label><label class="field"><span>Extra daily walking</span><select name="walking">${[0,15,20,25].map(n=>`<option value="${n}" ${p.walking==n?'selected':''}>${n} minutes</option>`).join('')}</select></label><label class="field"><span>Food preference</span><select name="diet">${[['all','Flexible'],['vegetarian','Vegetarian'],['vegan','Vegan'],['dairyfree','Dairy-free']].map(([v,t])=>`<option value="${v}" ${p.diet===v?'selected':''}>${t}</option>`).join('')}</select></label></div><h3 class="mt24">Available equipment</h3><div class="choice-grid">${['Bodyweight','Dumbbell','Barbell','Kettlebell'].map(v=>`<label class="choice"><input type="checkbox" name="equip" value="${v}" ${p.equipment.includes(v)?'checked':''}>${v==='Barbell'?'Connecting rod / barbell':v}</label>`).join('')}</div><div class="mt16"><button type="submit" class="btn btn-dark">Save preferences</button></div></form></div>
 <div><div class="card"><span class="eyebrow">LOCAL DATA · PRIVATE BY DEFAULT</span><h2 style="margin-top:12px">Your data, your control.</h2><p class="muted">This is a static website. ${cloudReady?'Measurements and workout entries sync to your signed-in Supabase account.':'Measurements and workout entries are stored in localStorage on this device.'} Clearing site data or using a different browser can erase them. A person using the same browser profile can view them, so do not use it for sensitive logging on shared devices.</p><div class="readout mb8">${cloudReady?'You are using a verified account with cloud sync. Avoid simultaneous edits on multiple devices.':'Guest profiles are not password-protected. Choose Account & sync to see whether secure accounts have been activated.'}</div><div class="flex gap8" style="flex-wrap:wrap">${button('Download JSON backup','data-action="backup"','btn btn-dark btn-sm')}${button('Download CSV measurements','data-action="csv"','btn btn-outline btn-sm')}</div><label class="field mt16"><span>Restore an exported FitPal backup</span><input id="importFile" type="file" accept="application/json,.json"></label><p class="footnote">Import creates a new profile, preserving existing profiles. Accepts FitPal v1 individual and v2 collection backups.</p><div class="divider"></div>${button('Delete ALL local profiles and records','data-action="delete-all"','btn btn-danger btn-sm')}</div><div class="card mt16"><h3>Public project ≠ public health data</h3><p class="muted">Never commit measurements, exported backups, individual health records or API secrets to a public GitHub repository. For better browser-level separation, deploy under a dedicated custom domain.</p><p class="footnote">Source library: <a class="link" href="https://github.com/bryllim/workout-guide" target="_blank" rel="noopener noreferrer">Workout Guide by Bryl Lim</a>. Original artwork by Everkinetic. Artwork CC BY-SA 4.0; no affiliation with the original artists is implied.</p></div></div></div>`}
function profileHub(){
 const cards=library.profiles.map(slot=>{
   const p=slot.data.profile,active=slot.id===library.activeId;
   const icon=AVATARS.includes(p.avatar)?p.avatar:'🌿';
   const sessions=Object.values(slot.data.sessions||{}).filter(s=>s?.completed).length;
   return `<div class="profile-card ${active?'profile-active':''}"><div class="profile-top"><div class="profile-avatar">${icon}</div><span class="chip ${active?'':'orange'}">${active?'CURRENT PROFILE':'LOCAL PROFILE'}</span></div>
     <h2>${escapeHTML(p.name||'Unnamed profile')}</h2><p class="muted">${escapeHTML(p.experience==='regular'?'Regular training':p.experience==='beginner'?'Getting started':'Building consistency')} · ${sessions} completed sessions</p>
     <p class="footnote">${escapeHTML(String(p.weeks==='47d'?'47 days':p.weeks+' weeks'))} · ${escapeHTML(String(p.duration||35))} min/session</p>
     <div class="profile-actions">${button(active?'Open dashboard':'Use profile',`data-profile-switch="${escapeHTML(slot.id)}"`,'btn btn-dark btn-sm')}${button('Edit',`data-profile-edit="${escapeHTML(slot.id)}"`,'btn btn-outline btn-sm')}${button('Delete',`data-profile-delete="${escapeHTML(slot.id)}"`,'btn btn-danger btn-sm')}</div></div>`;
 }).join('');
 return `<div class="page"><div class="page-head"><div><span class="eyebrow">YOUR LOCAL FITNESS SPACE</span><h1>Choose your profile.</h1><p>Create separate training spaces on this browser. Each profile has its own weight history, workouts, favorites, nutrition checklist and equipment preferences.</p></div>${button('+ Create profile','data-action="new-profile"','btn btn-dark')}</div>
   <div class="profile-privacy"><b>Private to this browser, not password-protected.</b> Other people using the same browser profile can open any local fitness profile. Optional email-verified cloud accounts may be enabled in Account & sync. Download a backup before clearing browser data or switching devices.</div>
   <div class="profiles-grid">${cards||`<div class="empty"><h2>No profiles yet</h2><p>Create your first profile to begin tracking workouts and measurements.</p>${button('Create my first profile','data-action="new-profile"')}</div>`}</div>
   <div class="card mt24"><h3>Personal data controls</h3><p class="muted">Profiles are stored entirely in browser localStorage. Save a full collection backup for safekeeping. Backup files can contain sensitive health measurements; never upload them to a public repository.</p><div class="flex gap8" style="flex-wrap:wrap">${button('Back up all profiles','data-action="backup-all"','btn btn-outline btn-sm')}<label class="btn btn-outline btn-sm" for="importFileAll" style="cursor:pointer">Import a backup</label><input type="file" id="importFileAll" accept="application/json,.json" class="visually-hidden"></div></div></div>`;
}
// ========== Recurring routine builder & customizable exercise slots ==========
const FOCUS_PRESETS=[
 {name:'Arms & biceps',kind:'Strength',ids:['row','curl','hammer','kickback'],sets:2},
 {name:'Upper-body strength',kind:'Strength',ids:['floor','row','press','curl'],sets:2},
 {name:'Lower-body strength',kind:'Strength',ids:['goblet','rdl','reverse','bridge'],sets:2},
 {name:'Core & posture',kind:'Strength',ids:['plank','deadbug','bird','side'],sets:2},
 {name:'Full-body essentials',kind:'Strength',ids:['goblet','row','floor','carry'],sets:2},
 {name:'Walking + abs',kind:'Cardio',ids:['walking','deadbug','crunch'],sets:2}
];
const allAvailableExercises=()=>{
 const core=Object.entries(exercises).filter(([id,e])=>!id.startsWith('catalog-')).map(([id,e])=>({id,...e}));
 const online=catalogStatus==='ready'?catalog.map(e=>({id:'catalog-'+e.slug,n:e.name,slug:e.slug,equip:e.equipment,muscle:e.primaryMuscle,type:e.isStretch?'mobility':e.exerciseType==='duration'?'core':e.equipment==='Cardio'?'cardio':'strength',reps:e.exerciseType==='duration'?'20–40 sec':'8–12',cue:'Review the illustrated frames. Use manageable resistance and comfortable, controlled technique.'})):[];
 const slugs=new Set();return [...core,...online].filter(e=>{if(slugs.has(e.slug))return false;slugs.add(e.slug);return true});
};
function makeDraft(r=null){return r?structuredClone(r):{id:newId(),title:'My personalized workout',kind:'Strength',sets:2,days:[1,3,5],active:true,startDate:currentDate,updatedAt:new Date().toISOString(),exercises:FOCUS_PRESETS[1].ids.map(id=>({id,...exercises[id]}))}}
function ensureDraft(){if(!routineDraft)routineDraft=makeDraft()}
const dayNames=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
function routineExerciseSearch(){const q=builderSearch.trim().toLowerCase();const available=new Set(['Bodyweight','Cardio','Wall','Chair',...db.profile.equipment]);return allAvailableExercises().filter(e=> (!builderHomeOnly||available.has(e.equip)) && (!builderMuscle||e.muscle===builderMuscle) && (!q||(e.n+' '+e.muscle+' '+e.equip).toLowerCase().includes(q))).slice(0,35)}
function routinesPage(){ensureDraft();if(catalogStatus==='unloaded')setTimeout(ensureAtlas,0);const presets=FOCUS_PRESETS.map((p,i)=>`<button type="button" data-routine-preset="${i}">${escapeHTML(p.name)}</button>`).join('');const existing=(db.routines||[]);
const summaries=existing.map(r=>`<div class="routine-card"><span class="eyebrow">${r.active!==false?'ACTIVE EACH WEEK':'PAUSED'} · ${escapeHTML(r.kind||'Strength')}</span><h3>${escapeHTML(r.title)}</h3><p>${(r.exercises||[]).length} exercises · ${r.sets||2} sets per movement</p><div>${(r.days||[]).map(d=>`<span class="routine-day">${dayNames[d]}</span>`).join('')}</div><div class="routine-actions"><button class="btn btn-dark btn-sm" data-routine-edit="${escapeHTML(r.id)}">Edit routine</button><button class="btn btn-outline btn-sm" data-routine-toggle="${escapeHTML(r.id)}">${r.active!==false?'Pause':'Resume'}</button><button class="btn btn-danger btn-sm" data-routine-delete="${escapeHTML(r.id)}">Delete</button></div></div>`).join('');
const choices=routineExerciseSearch().map(e=>`<button class="routine-pick" type="button" data-routine-add="${escapeHTML(e.id)}"><img src="${asset(e.slug,2)}" alt="" loading="lazy"><span><strong>${escapeHTML(e.n)}</strong><small>${escapeHTML(e.muscle)} · ${escapeHTML(e.equip)}</small></span><span class="add">+</span></button>`).join('');
return `<div class="page"><div class="routine-hero"><div><span class="eyebrow" style="color:#d9efb7">BUILD YOUR OWN TRAINING</span><h1>Make your week yours.</h1><p>Choose your muscles, your exercises and the weekdays you want to repeat them. Your selections take priority over the starter plan. Keep recovery days.</p></div><button class="btn" data-routine-new>+ New routine</button></div>
<div class="section-top"><div><h2>Your recurring routines</h2><p class="muted">On matching weekdays, the latest active routine becomes that day's workout.</p></div><span class="chip">${existing.length} saved</span></div>
${existing.length?`<div class="routine-card-grid">${summaries}</div>`:`<div class="routine-empty mb8">No custom routines yet. Select a template or build your first session below.</div>`}
<div class="section-top"><div><span class="eyebrow">WORKOUT COMPOSER</span><h2>${existing.some(r=>r.id===routineDraft.id)?'Edit your routine':'Create a routine'}</h2></div></div>
<div class="routine-layout"><div class="routine-build"><label class="field"><span>Routine name</span><input id="routineTitle" maxlength="75" value="${escapeHTML(routineDraft.title)}" placeholder="e.g. Monday arms & biceps"></label>
<div class="split-fields"><label class="field"><span>Training type</span><select id="routineKind">${['Strength','Cardio','Recovery'].map(t=>`<option ${routineDraft.kind===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>Sets per exercise</span><select id="routineSets">${[1,2,3,4].map(n=>`<option value="${n}" ${routineDraft.sets==n?'selected':''}>${n} sets</option>`).join('')}</select></label></div>
<label class="field"><span>Repeat each week on</span></label><div class="weekday-picks">${dayNames.map((d,i)=>`<label><input type="checkbox" data-routine-day="${i}" ${routineDraft.days.includes(i)?'checked':''}>${d}</label>`).join('')}</div>
<h3>Your selected exercises (${routineDraft.exercises.length})</h3><ol class="builder-selected">${routineDraft.exercises.map((e,i)=>`<li><span class="num">${i+1}</span><strong>${escapeHTML(e.n)}</strong><small>${escapeHTML(e.muscle)}</small><button aria-label="Remove ${escapeHTML(e.n)}" data-routine-remove="${escapeHTML(e.id)}">×</button></li>`).join('')}</ol>
<div class="routine-dim">Aim for 3–5 exercises in a 35-minute strength session; 6–8 may need more time. Suggested loads are examples, not strength tests.</div><div class="mini-row mt16"><button class="btn btn-dark" data-routine-save>Save recurring routine</button><button class="btn btn-outline" data-routine-new>Reset builder</button></div></div>
<div class="routine-build"><span class="eyebrow">START WITH A SUGGESTED SPLIT</span><div class="routine-presets">${presets}</div><h3>Choose exercises</h3><div class="builder-search"><input id="routineSearch" placeholder="Search biceps, squat, core..." value="${escapeHTML(builderSearch)}"><button class="btn btn-outline btn-sm" data-routine-search-clear>Clear</button></div>
<div class="split-fields"><label class="field"><span>Muscle focus</span><select id="routineMuscle"><option value="">All muscles</option>${[...new Set(allAvailableExercises().map(e=>e.muscle))].sort().map(x=>`<option ${builderMuscle===x?'selected':''}>${escapeHTML(x)}</option>`).join('')}</select></label><label class="field"><span>Equipment</span><select id="routineHome"><option value="home" ${builderHomeOnly?'selected':''}>My equipment</option><option value="all" ${!builderHomeOnly?'selected':''}>All exercises</option></select></label></div>
<p class="routine-dim">Browse the illustrated catalog (302 exercises when connected). Pick movements your equipment supports and practice safely.</p><div class="routine-picks">${choices||'<p class="muted">No exercises match your filters.</p>'}</div>${catalogStatus==='error'?'<p class="routine-dim">Full atlas offline. Curated exercises are still available.</p>':''}</div></div></div>`}
function addToDraft(id){ensureDraft();const e=allAvailableExercises().find(x=>x.id===id)||exercises[id]&&{id,...exercises[id]};if(!e)return;if(routineDraft.exercises.some(x=>x.id===id)){toast('Already in your routine.');return}if(routineDraft.exercises.length>=10){toast('Limit 10 exercises; consider two separate sessions.');return}const x={id:e.id,n:e.n,slug:e.slug,muscle:e.muscle,equip:e.equip,reps:e.reps,type:e.type,cue:e.cue,range:e.range||null,shape:e.shape||'one'};exercises[id]={...x};routineDraft.exercises.push(x);render()}
function saveRoutine(){ensureDraft();const title=String(routineDraft.title||'').trim();if(title.length<2){toast('Give the routine a descriptive name.');return}if(!routineDraft.days.length){toast('Select at least one weekday.');return}if(!routineDraft.exercises.length){toast('Add at least one exercise.');return}routineDraft.title=title;routineDraft.updatedAt=new Date().toISOString();db.routines=db.routines||[];const idx=db.routines.findIndex(x=>x.id===routineDraft.id);if(idx>=0)db.routines[idx]=structuredClone(routineDraft);else db.routines.push(structuredClone(routineDraft));persist();toast('Routine saved. It repeats each selected weekday.');routineDraft=makeDraft();render()}
function presetRoutine(i){const p=FOCUS_PRESETS[i];if(!p)return;ensureDraft();routineDraft.title=p.name;routineDraft.kind=p.kind;routineDraft.sets=p.sets;routineDraft.exercises=p.ids.map(id=>({id,...exercises[id]}));render()}
function showSwap(id){const entries=Object.entries(db.daySwaps?.[selected]||{});swapOrigin=entries.find(([origin,s])=>s?.id===id)?.[0]||id;const e=exercises[id];if(!e)return;if(catalogStatus==='unloaded')ensureAtlas();renderSwapChoices('');}
function renderSwapChoices(q){const origin=exercises[swapOrigin];if(!origin)return;const text=String(q||'').trim().toLowerCase();const compatible=new Set(['Bodyweight','Cardio','Wall','Chair',...db.profile.equipment]);const options=allAvailableExercises().filter(e=>compatible.has(e.equip) && e.slug!==origin.slug && (!text?e.muscle===origin.muscle:(e.n+' '+e.muscle).toLowerCase().includes(text))).slice(0,45);
$('modalBody').innerHTML=`<div class="modal-body"><span class="eyebrow">EXERCISE OPTIONS FOR THIS SESSION</span><h2 style="margin:9px 0">Replace ${escapeHTML(origin.n)}</h2><p class="muted">Choose an exercise you can do safely. This change applies only to ${niceDate(selected)}. Search by muscle or exercise name.</p><input class="swap-search" id="swapQuery" type="search" value="${escapeHTML(text)}" placeholder="Search all muscle groups, e.g. biceps, curl..."><div class="swap-results">${options.map(e=>`<button class="swap-item" data-swap-select="${escapeHTML(e.id)}"><img src="${asset(e.slug,2)}" alt="" loading="lazy"><span><b>${escapeHTML(e.n)}</b><small>${escapeHTML(e.muscle)} · ${escapeHTML(e.equip)}</small></span>→</button>`).join('')||'<p>No matches. Try a different search.</p>'}</div><button class="btn btn-outline btn-sm" data-swap-restore>Restore recommended exercise</button></div>`;
$('modal').hidden=false;document.body.style.overflow='hidden';}
function replaceExercise(id){const e=allAvailableExercises().find(x=>x.id===id)||exercises[id]&&{id,...exercises[id]};if(!e)return;exercises[id]={...e};db.daySwaps=db.daySwaps||{};if(!db.daySwaps[selected])db.daySwaps[selected]={};db.daySwaps[selected][swapOrigin]={id,meta:{...e}};persist();closeModal();render();toast('Exercise swapped for this day.')}
function restoreExercise(){if(db.daySwaps?.[selected])delete db.daySwaps[selected][swapOrigin];persist();closeModal();render();toast('Exercise restored.')}
function restoreSavedExerciseOptions(){for(const d of Object.values(db.daySwaps||{})){for(const item of Object.values(d||{})){if(item?.meta?.id&&!exercises[item.meta.id])exercises[item.meta.id]=item.meta}}}

function render(){uiHeader();if(page==='profiles'){$('content').innerHTML=profileHub();return}if(page==='account'){$('content').innerHTML=accountPage();return}if(creatingNewProfile||!hasProfile()){$('content').innerHTML=`<div class="page">${intro()}</div>`;return}const pages={dashboard,plan:planPage,routines:routinesPage,atlas:atlasPageHTML,progress:progressPage,nutrition:nutritionPage,settings:settingsPage,account:accountPage};$('content').innerHTML=pages[page]();if(page==='plan')refreshTimer()}
function formDataObj(f){return new FormData(f)}
function profileFromForm(fd,current=null){const equipment=fd.getAll('equip');const age=Number(fd.get('age')),height=Number(fd.get('height'));const start=fd.get('start');const maxDB=Number(fd.get('maxDB'));
 if(!Number.isFinite(age)||age<18||age>100||height<100||height>240||!/^\d{4}-\d{2}-\d{2}$/.test(start)||!Number.isFinite(maxDB)||maxDB<0||maxDB>150)throw Error('Check the profile fields. This prototype is designed for adults.');
 if(!equipment.includes('Bodyweight'))equipment.push('Bodyweight');const name=String(fd.get('name')||'').trim().slice(0,35);if(!name)throw Error('Please enter a profile name.');return {...(current||{}),name,avatar:AVATARS.includes(fd.get('avatar'))?fd.get('avatar'):'🌿',age,height,equipment,maxDB,experience:fd.get('experience'),duration:Number(fd.get('duration')),walking:Number(fd.get('walking')),weeks:fd.get('weeks')==='47d'?'47d':Number(fd.get('weeks')),diet:fd.get('diet'),startDate:start};}
function createProfile(form){try{const fd=formDataObj(form),p=profileFromForm(fd);const weight=kgWeight(fd.get('weight'));const goal=fd.get('goal')?kgWeight(fd.get('goal')):null;if(!Number.isFinite(weight)||weight<20||weight>400||goal!==null&&(!Number.isFinite(goal)||goal<20||goal>400))throw Error('Please check weight entries.');p.startWeightKg=weight;p.goalWeightKg=goal;addProfileData({profile:p,unit:db.unit,measurements:[{date:p.startDate,weightKg:weight,waistCm:null,baseline:true}],sessions:{},favorites:[],shopping:[],routines:[],daySwaps:{}});selected=p.startDate;page='dashboard';creatingNewProfile=false;minuteTimer=p.duration*60;render();toast('New local profile created.');}catch(e){toast(e.message)}}
function savePrefs(form){try{const fd=formDataObj(form);const p=profileFromForm(fd,db.profile);p.goalWeightKg=fd.get('goal')?kgWeight(fd.get('goal')):null;if(p.goalWeightKg!==null&&(!Number.isFinite(p.goalWeightKg)||p.goalWeightKg<20||p.goalWeightKg>400))throw Error('Enter a valid goal weight.');const moved=p.startDate!==db.profile.startDate;if(moved && !confirm('Changing the plan start date changes the workout-date mapping. Existing session records remain on their original dates. Continue?'))return;db.profile=p;selected=datePlus(p.startDate,safeIndex(selected));minuteTimer=p.duration*60;persist();render();toast('Preferences saved.')}catch(e){toast(e.message)}}
function addMeasurement(form){const fd=formDataObj(form),date=String(fd.get('date')),weight=kgWeight(fd.get('weight')),waist=fd.get('waist')?Number(fd.get('waist')):null;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(weight)||weight<20||weight>400||waist!==null&&(waist<30||waist>250)){toast('Check weight and waist values.');return}const existing=db.measurements.find(x=>x.date===date);if(existing?.baseline&&!confirm('This is your baseline date. The starting weight will remain unchanged in your plan. Save this log too?'))return;db.measurements=db.measurements.filter(x=>x.date!==date);db.measurements.push({date,weightKg:weight,waistCm:waist,baseline:Boolean(existing?.baseline)});db.measurements.sort((a,b)=>a.date.localeCompare(b.date));persist();render();toast('Measurement saved privately.')} 
function refreshTimer(){const el=$('timerNumber');if(el)el.innerHTML=`${D(Math.floor(minuteTimer/60))}:${D(minuteTimer%60)} <span>min</span>`}
function stopTimer(){if(timer){clearInterval(timer);timer=null}}
function tickTimer(){minuteTimer=Math.max(0,minuteTimer-1);refreshTimer();if(minuteTimer===0){stopTimer();toast('Session timer finished. Well done!');if(page==='plan')render()}}
function saveJSON(){download('rebuild-profile-'+currentDate+'.json',JSON.stringify({format:'rebuild-public-v1',exportedAt:new Date().toISOString(),data:db},null,2))}
function saveAllJSON(){download('rebuild-all-profiles-'+currentDate+'.json',JSON.stringify({format:'rebuild-profiles-v2',exportedAt:new Date().toISOString(),data:library},null,2))}
function csvMeasurements(){const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';const rows=[['date','weight_kg','waist_cm'],...db.measurements.map(x=>[x.date,x.weightKg,x.waistCm])];download('rebuild-measurements-'+currentDate+'.csv',rows.map(x=>x.map(esc).join(',')).join('\n'),'text/csv')}
async function importFile(file){
 if(!file)return;
 if(file.size>8*1024*1024){toast('That file is too large.');return}
 try{
   const incoming=JSON.parse(await file.text());
   let arrivals=[];
   if(incoming.format==='rebuild-public-v1' && validData(incoming.data))arrivals=[incoming.data];
   else if(incoming.format==='rebuild-profiles-v2'&&incoming.data?.version===2&&Array.isArray(incoming.data.profiles)){
     arrivals=incoming.data.profiles.filter(s=>validData(s.data)).map(s=>s.data);
     if(arrivals.length!==incoming.data.profiles.length)throw Error('A profile in this backup is invalid.');
   }else throw Error('Unsupported or incomplete FitPal backup.');
   if(!arrivals.length||arrivals.length>30||library.profiles.length+arrivals.length>30)throw Error('Import would exceed the 30-profile limit.');
   if(!confirm('Import '+arrivals.length+' profile(s) as NEW local profiles? Your existing profiles will be preserved.'))return;
   for(const data of arrivals){
     const safe={...defaultStore(),...data};safe.measurements=safe.measurements.slice(0,1000);safe.favorites=Array.isArray(safe.favorites)?safe.favorites.slice(0,302):[];
     const id=newId();library.profiles.push({id,createdAt:new Date().toISOString(),data:safe});library.activeId=id;
   }
   openActiveProfile();persist();render();toast(arrivals.length+' profile(s) imported.');
 }catch(e){toast(e.message||'Could not import backup.');}
}

function action(type,button){if(type==='today'){const t=hasProfile()?db.profile.startDate:currentDate;const diff=dateDiff(currentDate,t);selected=datePlus(t,Math.max(0,Math.min(planLength()-1,diff)));page='plan';render();return}
 if(type==='previous-week'||type==='next-week'){selectDate(datePlus(selected,type==='previous-week'?-7:7));return}
 if(type==='finish'){const s=getSession(selected);s.completed=!s.completed;persist();render();toast(s.completed?'Session recorded. Great work.':'Session marked unfinished.');return}
 if(type==='timer'){if(timer){stopTimer();render();return}timer=setInterval(tickTimer,1000);render();return}
 if(type==='reset-timer'){stopTimer();minuteTimer=db.profile.duration*60;render();return}
 if(type==='atlas-clear'){atlasSearch='';atlasEquipment='home';atlasMuscle='';atlasPage=0;showFavorites=false;render();return}
 if(type==='atlas-home'){atlasEquipment=atlasEquipment==='home'?'':'home';atlasPage=0;render();return}
 if(type==='atlas-favorites'){showFavorites=!showFavorites;atlasPage=0;render();return}
 if(type==='atlas-more'){atlasPage++;render();return}
 if(type==='retry-atlas'){catalogStatus='unloaded';ensureAtlas();return}
 if(type==='clear-shopping'){db.shopping=[];persist();render();toast('Shopping checklist cleared.');return}
 if(type==='new-profile'){creatingNewProfile=true;page='setup';render();return}
 if(type==='backup-all'){saveAllJSON();return}
 if(type==='backup'){saveJSON();return}
 if(type==='csv'){csvMeasurements();return}
 if(type==='delete-all'){if(cloudReady){toast('Cloud profiles are not deleted by clearing guest data. Contact the operator to delete the online account.');return}if(!confirm('Delete ALL FitPal local profiles, weight logs and workout history from this browser? This cannot be undone. Export a full backup first.'))return;const answer=prompt('Type DELETE ALL to permanently erase EVERY profile on this browser.');if(answer!=='DELETE ALL')return;library={version:2,profiles:[],activeId:null};db=defaultStore();try{localStorage.removeItem(MULTI_STORAGE);localStorage.removeItem(STORAGE)}catch(e){}stopTimer();page='profiles';selected=currentDate;render();toast('All local profiles deleted.');return}
}
document.addEventListener('click',ev=>{
 const rNew=ev.target.closest('[data-routine-new]');if(rNew){routineDraft=makeDraft();render();return}
 const preset=ev.target.closest('[data-routine-preset]');if(preset){presetRoutine(Number(preset.dataset.routinePreset));return}
 const rAdd=ev.target.closest('[data-routine-add]');if(rAdd){addToDraft(rAdd.dataset.routineAdd);return}
 const rRem=ev.target.closest('[data-routine-remove]');if(rRem){routineDraft.exercises=routineDraft.exercises.filter(x=>x.id!==rRem.dataset.routineRemove);render();return}
 const rSave=ev.target.closest('[data-routine-save]');if(rSave){saveRoutine();return}
 const rEdit=ev.target.closest('[data-routine-edit]');if(rEdit){const r=(db.routines||[]).find(x=>x.id===rEdit.dataset.routineEdit);if(r){routineDraft=makeDraft(r);render()}return}
 const rToggle=ev.target.closest('[data-routine-toggle]');if(rToggle){const r=(db.routines||[]).find(x=>x.id===rToggle.dataset.routineToggle);if(r){r.active=r.active===false;r.updatedAt=new Date().toISOString();persist();render()}return}
 const rDelete=ev.target.closest('[data-routine-delete]');if(rDelete){const r=(db.routines||[]).find(x=>x.id===rDelete.dataset.routineDelete);if(r&&confirm('Delete recurring routine "'+r.title+'"? Your recorded workout logs will remain.')){db.routines=db.routines.filter(x=>x.id!==r.id);persist();routineDraft=makeDraft();render()}return}
 const clearSearch=ev.target.closest('[data-routine-search-clear]');if(clearSearch){builderSearch='';render();return}
 const swapButton=ev.target.closest('[data-swap]');if(swapButton){showSwap(swapButton.dataset.swap);return}
 const swapPick=ev.target.closest('[data-swap-select]');if(swapPick){replaceExercise(swapPick.dataset.swapSelect);return}
 const swapRestore=ev.target.closest('[data-swap-restore]');if(swapRestore){restoreExercise();return}
 const link=ev.target.closest('[data-page]');if(link){navigate(link.dataset.page);return}
 const btn=ev.target.closest('[data-action]');if(btn){action(btn.dataset.action,btn);return}
 const swap=ev.target.closest('[data-profile-switch]');if(swap){const id=swap.dataset.profileSwitch;if(library.profiles.some(s=>s.id===id)){library.activeId=id;openActiveProfile();persist();render();toast('Profile switched.')}return}
 const edit=ev.target.closest('[data-profile-edit]');if(edit){const id=edit.dataset.profileEdit;if(library.profiles.some(s=>s.id===id)){library.activeId=id;openActiveProfile();persist();page='settings';render();}return}
 const delProfile=ev.target.closest('[data-profile-delete]');if(delProfile){const id=delProfile.dataset.profileDelete;const target=library.profiles.find(s=>s.id===id);if(!target)return;
   if(!confirm('Permanently delete profile "'+(target.data.profile.name||'Unnamed')+'" and ALL its workouts and measurements from this browser?'))return;
   const answer=prompt('Type DELETE to confirm deleting this profile.');if(answer!=='DELETE')return;
   library.profiles=library.profiles.filter(s=>s.id!==id);if(library.activeId===id)library.activeId=library.profiles[0]?.id||null;
   openActiveProfile();persist();page='profiles';render();toast('Local profile deleted.');return}
 const dateBtn=ev.target.closest('[data-date]');if(dateBtn){selectDate(dateBtn.dataset.date);return}
 const mini=ev.target.closest('[data-exercise]');if(mini){openExercise(mini.dataset.exercise,true);return}
 const a=ev.target.closest('[data-atlas-view]');if(a){openExercise(a.dataset.atlasView);return}
 const fav=ev.target.closest('[data-atlas-fav]');if(fav){const slug=fav.dataset.atlasFav;db.favorites=db.favorites.includes(slug)?db.favorites.filter(s=>s!==slug):[...db.favorites,slug];persist();render();return}
 const del=ev.target.closest('[data-del-measure]');if(del){if(!confirm('Delete this measurement entry?'))return;db.measurements=db.measurements.filter(x=>x.date!==del.dataset.delMeasure);persist();render();toast('Measurement removed.');return}
 const pause=ev.target.closest('[data-pause-motion]');if(pause){const loop=pause.closest('.exercise-visual').querySelector('.motion-loop');const stopped=loop.classList.toggle('paused');pause.textContent=stopped?'Play animation':'Pause animation';return}
 const close=ev.target.closest('[data-close-modal]');if(close){closeModal();return}
 if(ev.target===$('modal'))closeModal();
});
document.addEventListener('submit',ev=>{if(ev.target.id==='authForm'){ev.preventDefault();submitAuthForm(ev.target);return}else if(ev.target.id==='passwordForm'){ev.preventDefault();changePassword(ev.target);return}else if(ev.target.id==='onboardForm'){ev.preventDefault();createProfile(ev.target)}else if(ev.target.id==='preferencesForm'){ev.preventDefault();savePrefs(ev.target)}else if(ev.target.id==='measurementForm'){ev.preventDefault();addMeasurement(ev.target)}});
document.addEventListener('change',ev=>{
 const el=ev.target;
 if(el.id==='routineKind'){routineDraft.kind=el.value;return}
 if(el.id==='routineSets'){routineDraft.sets=Number(el.value);return}
 if(el.id==='routineMuscle'){builderMuscle=el.value;render();return}
 if(el.id==='routineHome'){builderHomeOnly=el.value==='home';render();return}
 if(el.matches('[data-routine-day]')){const d=Number(el.dataset.routineDay);routineDraft.days=el.checked?[...new Set([...routineDraft.days,d])]:routineDraft.days.filter(x=>x!==d);return}

 if(el.matches('[data-check]')){const [id,index]=el.dataset.check.split('|');getSet(selected,id,Number(index)).done=el.checked;persist();toast(el.checked?'Set logged.':'Set unchecked.');return}
 if(el.matches('[data-set-field]')){const [id,index,field]=el.dataset.setField.split('|');const target=getSet(selected,id,Number(index));if(el.value===''){target[field]=field==='weightKg'?null:''}else if(field==='reps'){target.reps=Math.max(0,Math.min(300,Number(el.value)||0))}else{const n=kgWeight(el.value);target.weightKg=Number.isFinite(n)?Math.max(0,Math.min(500,n)):null}persist();return}
 if(el.id==='didWalking'){getSession(selected).walked=el.checked;persist();return}
 if(el.id==='atlasEquipment'){atlasEquipment=el.value;atlasPage=0;render();return}
 if(el.id==='atlasMuscle'){atlasMuscle=el.value;atlasPage=0;render();return}
 if(el.matches('[data-food]')){const n=el.dataset.food;db.shopping=el.checked?[...new Set([...db.shopping,n])]:db.shopping.filter(x=>x!==n);persist();return}
 if(el.id==='importFile'||el.id==='importFileAll'){importFile(el.files?.[0]);return}
 if(el.id==='sessionNotes'){getSession(selected).notes=el.value.slice(0,1500);persist();return}
});
document.addEventListener('input',ev=>{if(ev.target.id==='atlasQuery'){atlasSearch=ev.target.value;atlasPage=0;const cursor=ev.target.selectionStart;render();const input=$('atlasQuery');if(input){input.focus();try{input.setSelectionRange(cursor,cursor)}catch(e){}}}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!$('modal').hidden)closeModal()});
$('unitButton').addEventListener('click',()=>{db.unit=db.unit==='kg'?'lb':'kg';persist();render();toast('Displaying weights in '+db.unit)});
openActiveProfile();
if(!activeSlot())page='profiles';
render();
let routineSearchTimer;
document.addEventListener('input',ev=>{
 if(ev.target.id==='routineTitle'){routineDraft.title=ev.target.value;return}
 if(ev.target.id==='routineSearch'){builderSearch=ev.target.value;clearTimeout(routineSearchTimer);routineSearchTimer=setTimeout(()=>{const focus=document.activeElement?.id==='routineSearch';const pos=focus?document.activeElement.selectionStart:0;render();const el=$('routineSearch');if(focus&&el){el.focus();el.setSelectionRange(pos,pos)}},240);return}
 if(ev.target.id==='swapQuery'){const q=ev.target.value;const pos=ev.target.selectionStart;renderSwapChoices(q);const el=$('swapQuery');if(el){el.focus();el.setSelectionRange(pos,pos)}return}
});

// Optional verified cloud accounts (Supabase). The app works without a backend.
const AUTH_CONFIG=window.FITPAL_CONFIG||{};
let authMode='signin',cloudError='',cloudSaving=false,cloudLastSaved='',authInitialized=false;
const isConfigured=()=>/^https:\/\/.+\.supabase\.co\/?$/.test(AUTH_CONFIG.supabaseUrl||'') && /^(sb_publishable_|eyJ)/.test(AUTH_CONFIG.publishableKey||'');
function accountPage(){
 const cfg=isConfigured();const login=Boolean(cloudUser&&cloudReady);
 const status=login?`<div class="auth-state">✓ Verified cloud account · ${escapeHTML(cloudUser.email||'')}</div>`:cfg?`<div class="auth-state warn">Cloud accounts are optional. Keep using a local profile without signing in.</div>`:`<div class="auth-state warn">Email signup is prepared but not activated. The site operator must configure Supabase first. Guest profiles work now.</div>`;
 const cloudUI=login?`<div class="card"><h2>Your cloud account</h2><p class="muted">Signed in as <b>${escapeHTML(cloudUser.email||'')}</b>. Workout logs and measurements sync to your private Supabase record with row-level security.</p>${cloudError?`<div class="auth-state warn">${escapeHTML(cloudError)}</div>`:''}
 <div class="auth-state">${cloudSaving?'Saving updates…':cloudLastSaved?'Saved to cloud '+escapeHTML(cloudLastSaved):'Cloud is ready'}</div>
 <div class="account-buttons"><button class="btn btn-outline" data-auth-action="sync">Sync now</button>${guestLibrary?.profiles?.length?'<button class="btn btn-dark" data-auth-action="import-guest">Copy previous browser profile into account</button>':''}<button class="btn btn-danger" data-auth-action="signout">Sign out</button></div><p class="auth-small mt16">Do not use a shared browser to store sensitive data. Account removal requests require the service operator; deleting local data does not delete the authentication account.</p></div>`:
 `<div class="card"><h2>${passwordRecovery?'Choose a new password':authMode==='signup'?'Create a verified account':authMode==='reset'?'Reset your password':'Sign in to FitPal'}</h2><p class="muted">${cfg?'With an account you can access your fitness data on multiple devices. Email verification is required by the configured provider.':'Guest workout planning and tracking do not require an account.'}</p>
 ${passwordRecovery?`<form id="passwordForm" class="auth-form"><label class="field">New password <input class="auth-input" type="password" name="password" autocomplete="new-password" minlength="10" required></label><button class="btn btn-dark" type="submit">Set new password</button></form>`:
 `<form id="authForm" class="auth-form"><label class="field">Email address<input class="auth-input" name="email" type="email" autocomplete="email" placeholder="you@example.com" required ${!cfg?'disabled':''}></label>
 ${authMode!=='reset'?`<label class="field">Password<input class="auth-input" name="password" type="password" autocomplete="${authMode==='signup'?'new-password':'current-password'}" minlength="10" required ${!cfg?'disabled':''}></label>`:''}
 <button class="btn btn-dark" type="submit" ${cfg?'':'disabled'}>${authMode==='signup'?'Create account & send verification':authMode==='reset'?'Send reset link':'Sign in'}</button></form><div class="account-buttons mt16"><button class="btn btn-outline btn-sm" data-auth-mode="signin">Sign in</button><button class="btn btn-outline btn-sm" data-auth-mode="signup">Register</button><button class="btn btn-outline btn-sm" data-auth-mode="reset">Forgot password?</button></div>`}
 ${!cfg?'<p class="auth-small mt16">Operator setup: enter the public Supabase project URL and publishable key in config.js; run the supplied database schema and configure email redirects. No secret key belongs in GitHub.</p>':''}</div>`;
 return `<div class="page"><div class="page-head"><div><span class="eyebrow">FITPAL ACCOUNT · OPTIONAL</span><h1>Your training, wherever you are.</h1><p>Use a private guest profile or activate email-verified cloud synchronization. Public exercise guides remain available without an account.</p></div></div>${status}<div class="auth-grid"><div>${cloudUI}</div><div class="auth-bene"><span class="eyebrow">ACCOUNT BENEFITS</span><h3>Your habits, saved.</h3><p>✓ Private weight and waist history<br>✓ Recurring weekly workouts<br>✓ Chosen exercises, sets and loads<br>✓ Consistent progress across devices<br>✓ No public GitHub storage of personal records</p><hr style="border:0;border-top:1px solid #cfe0c4;margin:19px 0"><p class="auth-small"><strong>Guest mode:</strong> profiles and logs remain in this browser. Use the export feature as a backup. <strong>Cloud mode:</strong> requires a Supabase project and a confirmed email address.</p><button class="btn btn-dark btn-sm" data-page="profiles">Continue as guest</button></div></div></div>`;
}
function accountRedirect(){return location.origin+location.pathname+'#account'}
async function loadAuthLibrary(){if(!isConfigured())return false;if(window.supabase?.createClient)return true;return new Promise((resolve)=>{
 const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.js';script.async=true;script.onload=()=>resolve(!!window.supabase?.createClient);script.onerror=()=>resolve(false);document.head.appendChild(script);
});}
async function initSupabaseAuth(){if(authInitialized||!isConfigured())return;authInitialized=true;
 try{if(!await loadAuthLibrary())throw Error('Could not load the authentication library');
 cloudClient=window.supabase.createClient(AUTH_CONFIG.supabaseUrl,AUTH_CONFIG.publishableKey,{auth:{autoRefreshToken:true,persistSession:true,detectSessionInUrl:true}});
 cloudClient.auth.onAuthStateChange((event,session)=>{
   if(event==='PASSWORD_RECOVERY'){passwordRecovery=true;page='account';render();return}
   if(event==='SIGNED_OUT'){if(cloudReady)handleSignedOut();return}
   if(session?.user&&(event==='SIGNED_IN'||event==='INITIAL_SESSION'||event==='TOKEN_REFRESHED')){
      if(!cloudReady || cloudUser?.id!==session.user.id)setTimeout(()=>loadCloudProfile(session.user),0);
   }
 });
 const {data,error}=await cloudClient.auth.getUser();if(error && !/Auth session missing/i.test(error.message||''))throw error;
 if(data?.user)await loadCloudProfile(data.user);
 }catch(e){cloudError=e.message;console.warn('FitPal optional account configuration:',e.message);if(page==='account')render();}
}
async function loadCloudProfile(user){if(!cloudClient||!user?.id)return;
 try{
   const {data,error}=await cloudClient.from('user_fitness_state').select('payload').eq('user_id',user.id).maybeSingle();if(error)throw error;
   if(!cloudReady)guestLibrary=structuredClone(loadProfiles());
   cloudUser=user;cloudReady=true;cloudError='';
   const payload=data?.payload;
   if(payload?.version===2 && Array.isArray(payload.profiles)){
     const profiles=payload.profiles.filter(x=>x?.id&&validData(x.data)).slice(0,30);
     library={version:2,profiles,activeId:profiles.some(x=>x.id===payload.activeId)?payload.activeId:profiles[0]?.id||null};
   } else library={version:2,profiles:[],activeId:null};
   openActiveProfile();page='account';render();toast('Cloud account connected.');
 }catch(e){cloudError='Could not load your cloud profile: '+e.message;cloudReady=false;cloudUser=null;if(page==='account')render();}
}
function scheduleCloudSave(){if(!cloudClient||!cloudReady||!cloudUser)return;clearTimeout(cloudTimer);cloudTimer=setTimeout(syncCloudNow,1100)}
async function syncCloudNow(){if(!cloudReady||!cloudUser||!cloudClient)return;
 clearTimeout(cloudTimer);cloudSaving=true;const userId=cloudUser.id;const payload=structuredClone(library);
 try{const {error}=await cloudClient.from('user_fitness_state').upsert({user_id:userId,payload,updated_at:new Date().toISOString()},{onConflict:'user_id'});
   if(error)throw error;cloudLastSaved=new Date().toLocaleTimeString();cloudError='';
 }catch(e){cloudError='Sync failed: '+e.message;toast('Cloud sync failed. Export a backup before closing the tab.');}finally{cloudSaving=false;if(page==='account')render()}
}
function handleSignedOut(){cloudReady=false;cloudUser=null;clearTimeout(cloudTimer);cloudError='';cloudLastSaved='';library=guestLibrary||loadProfiles();guestLibrary=null;openActiveProfile();page='account';render();toast('Signed out. Your browser guest profiles are available.');}
async function submitAuthForm(form){if(authBusy||!cloudClient){toast('Email accounts are not activated yet.');return}
 const fd=new FormData(form),email=String(fd.get('email')||'').trim().toLowerCase(),password=String(fd.get('password')||'');
 if(!email||authMode!=='reset' && password.length<10){toast('Use a valid email and a password of at least 10 characters.');return}
 authBusy=true;try{
  let error=null;
  if(authMode==='signup')({error}=await cloudClient.auth.signUp({email,password,options:{emailRedirectTo:accountRedirect()}}));
  else if(authMode==='reset')({error}=await cloudClient.auth.resetPasswordForEmail(email,{redirectTo:accountRedirect()}));
  else ({error}=await cloudClient.auth.signInWithPassword({email,password}));
  if(error)throw error;
  toast(authMode==='signup'?'Check your inbox for the verification link.':authMode==='reset'?'If the address is registered, you will receive a password reset link.':'Signing in…');
 }catch(e){toast(e.message||'Authentication request failed.')}finally{authBusy=false;form.querySelector('[name="password"]')?.setAttribute('value','');}
}
async function changePassword(form){if(!cloudClient)return;try{const password=String(new FormData(form).get('password')||'');if(password.length<10)throw Error('Use at least 10 characters');const {error}=await cloudClient.auth.updateUser({password});if(error)throw error;passwordRecovery=false;toast('Password changed.');render()}catch(e){toast(e.message)}}
async function authAction(action){if(!cloudClient){toast('Cloud accounts are not configured.');return}
 if(action==='signout'){
  if(cloudReady)await syncCloudNow();const {error}=await cloudClient.auth.signOut();if(error){toast(error.message);return}handleSignedOut();return}
 if(action==='sync'){await syncCloudNow();toast(cloudError||'Cloud data synchronized.');return}
 if(action==='import-guest'){
  const src=guestLibrary?.profiles?.find(p=>p.id===guestLibrary.activeId);if(!src)return;
  if(!confirm('Copy the previous guest profile and its records to your cloud account? Your current cloud profiles will remain.'))return;
  if(library.profiles.length>=30){toast('Cloud profile limit reached.');return}
  const data=structuredClone(src.data);const id=newId();library.profiles.push({id,createdAt:new Date().toISOString(),data});library.activeId=id;openActiveProfile();await syncCloudNow();page='account';render();toast(cloudError||'Guest profile copied to your account.');return;
 }
}
document.addEventListener('click',ev=>{
 const mode=ev.target.closest('[data-auth-mode]');if(mode){authMode=mode.dataset.authMode;render();return}
 const btn=ev.target.closest('[data-auth-action]');if(btn){authAction(btn.dataset.authAction);return}
});
